mapper.select:
SELECT * FROM WEATHER_REMINDER_TASK
WHERE LOCATION = #{location}
  AND AVAILABLE = 1
  AND EXPECTED_EARLIEST_TIME <= #{currentTime}
  AND (TASK_STATUS = 0 OR TASK_TYPE = 1)
ORDER BY CREATE_TIME DESC

mapper.update:
UPDATE WEATHER_REMINDER_TASK
SET TASK_STATUS = #{status}, UPDATE_TIME = NOW()
WHERE ID = #{id}

UPDATE WEATHER_REMINDER_TASK
SET AVAILABLE = #{available}, UPDATE_TIME = NOW()
WHERE ID = #{id}
